      question: "How do you handle errors in Node.js applications?",
      answer: "Error handling patterns: try-catch in synchronous code, error-first callbacks, promise.catch(), async/await with try-catch, process.on('uncaughtException'), event emitters error event, Express error middleware.",
      example: "// Error-first callbacks\nconst fs = require('fs');\nfs.readFile('file.txt', 'utf8', (err, data) => {\n  if (err) {\n    console.error('Read error:', err.message);\n    return;\n  }\n  console.log(data);\n});\n\n// Promises with catch\nconst readFile = require('fs').promises;\nreadFile('file.txt', 'utf8')\n  .then(data => console.log(data))\n  .catch(err => console.error('Error:', err.message));\n\n// Async/await with try-catch\nasync function readConfig() {\n  try {\n    const data = await readFile('config.json', 'utf8');\n    return JSON.parse(data);\n  } catch (err) {\n    console.error('Config load failed:', err.message);\n    return { port: 3000 }; // Default config\n  }\n}\n\n// Global error handlers\nprocess.on('uncaughtException', (err) => {\n  console.error('Uncaught Exception:', err);\n  // Clean up and exit\n  process.exit(1);\n});\n\nprocess.on('unhandledRejection', (err) => {\n  console.error('Unhandled Rejection:', err);\n});\n\n// Event emitter errors\nconst EventEmitter = require('events');\nconst emitter = new EventEmitter();\nemitter.on('error', (err) => console.error('Emitter error:', err.message));\nemitter.emit('error', new Error('Something failed'));",
