      question: "What is the File System (fs) module used for?",
      answer: "fs module provides file system operations: reading, writing, deleting, renaming files and directories. Supports both synchronous and asynchronous methods. Asynchronous is preferred for production.",
      example: "const fs = require('fs');\nconst fsPromises = require('fs').promises;\n\n// ========== ASYNCHRONOUS (Callback) ==========\nfs.readFile('input.txt', 'utf8', (err, data) => {\n  if (err) throw err;\n  console.log('File content:', data);\n});\n\nfs.writeFile('output.txt', 'Hello World', (err) => {\n  if (err) throw err;\n  console.log('File written');\n});\n\nfs.appendFile('log.txt', 'New entry\\n', (err) => {\n  if (err) throw err;\n});\n\n// ========== PROMISES (modern) ==========\nasync function fileOperations() {\n  try {\n    await fsPromises.writeFile('data.txt', 'Content');\n    const data = await fsPromises.readFile('data.txt', 'utf8');\n    console.log('Data:', data);\n    \n    await fsPromises.appendFile('data.txt', '\\nMore content');\n    \n    const stats = await fsPromises.stat('data.txt');\n    console.log('File size:', stats.size, 'bytes');\n    console.log('Is file:', stats.isFile());\n    console.log('Modified:', stats.mtime);\n  } catch (err) {\n    console.error('Error:', err);\n  }\n}\n\n// ========== SYNCHRONOUS (Blocking) ==========\ntry {\n  const data = fs.readFileSync('config.json', 'utf8');\n  console.log('Config:', JSON.parse(data));\n  \n  fs.writeFileSync('backup.json', data);\n  fs.unlinkSync('temp.txt'); // Delete file\n} catch (err) {\n  console.error('Sync error:', err);\n}\n\n// Directory operations\nfs.mkdir('uploads', { recursive: true }, (err) => {\n  if (err) throw err;\n  console.log('Directory created');\n});\n\nfs.readdir('uploads', (err, files) => {\n  console.log('Files:', files);\n});\n\n// Watch file changes\nfs.watch('config.json', (eventType, filename) => {\n  console.log(`${filename} changed: ${eventType}`);\n});\n\n// Check if file exists\nif (fs.existsSync('important.txt')) {\n  console.log('File exists');\n}",
