      question: "What are child processes in Node.js? How to create them?",
      answer: "Child processes allow running external commands or other scripts. Methods: exec (buffered output), spawn (streamed output), fork (Node.js module), execFile (executable file).",
      example: "const { exec, spawn, fork, execFile } = require('child_process');\n\n// exec - buffers output (good for small outputs)\nexec('ls -la', (error, stdout, stderr) => {\n  if (error) {\n    console.error(`Error: ${error.message}`);\n    return;\n  }\n  console.log(`Files: ${stdout}`);\n});\n\n// spawn - streams output (good for large outputs)\nconst ls = spawn('ls', ['-la', '/usr']);\nls.stdout.on('data', (data) => {\n  console.log(`Output: ${data}`);\n});\nls.stderr.on('data', (data) => {\n  console.error(`Error: ${data}`);\n});\nls.on('close', (code) => {\n  console.log(`Process exited with code ${code}`);\n});\n\n// execFile - execute file\nconst { execFile } = require('child_process');\nexecFile('node', ['--version'], (error, stdout, stderr) => {\n  if (error) throw error;\n  console.log(`Node version: ${stdout}`);\n});\n\n// fork - create Node.js process\nconst child = fork('child.js');\nchild.on('message', (msg) => {\n  console.log('Parent received:', msg);\n});\nchild.send({ hello: 'world' });\n\n// child.js\nprocess.on('message', (msg) => {\n  console.log('Child received:', msg);\n  process.send({ pong: 'received' });\n});\n\n// Spawn with options\nconst python = spawn('python', ['script.py'], {\n  cwd: '/path/to/script',\n  env: { ...process.env, PYTHONPATH: '/custom/path' },\n  stdio: 'pipe'\n});\n\n// Execute with timeout\nexec('long-running-command', { timeout: 5000 }, (err, stdout) => {\n  if (err && err.killed) {\n    console.log('Process timed out after 5 seconds');\n  }\n});",
